#include <stdio.h>
#include <stdlib.h>

int main(int argc, char **argv) {
    if (argc < 2) {
        printf("Usage: %s <expression>\n", argv[0]);
        return 1;
    }

    int stack[64];
    int top = 0;

    for (int i = 1; i < argc; i++) {
        char *token = argv[i];
        if (token[0] == '+' || token[0] == '-' || token[0] == '*' || token[0] == '/') {
            if (top < 2) {
                printf("ERROR\n");
                return 1;
            }
            int b = stack[top - 1];
            int a = stack[top - 2];
            top -= 2;
            int result;
            switch (token[0]) {
                case '+':
                    result = a + b;
                    break;
                case '-':
                    result = a - b;
                    break;
                case '*':
                    result = a * b;
                    break;
                case '/':
                    result = a / b;
                    break;
            }
            stack[top++] = result;
        } else {
            int num = atoi(token);
            stack[top++] = num;
        }
    }

    if (top != 1) {
        printf("ERROR\n");
        return 1;
    }

    printf("%d\n", stack[0]);
    return 0;
}
